{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "Eighty per cent of chronic non-communicable disease (NCD) mortality occurs in developing countries, particularly in Africa. 1 The most common NCDs include cardiovascular diseases, diabetes, cancer and chronic respiratory diseases, 2 with positive correlation between NCDs and bone and joint disorders. 3 ... However, independent of gender, ethnicity and income, more than half of all adults in Africa are inactive.",
      "reason": "The authors describe the current state of knowledge regarding the burden of NCDs and physical inactivity in Africa."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "No systematic review has examined the effects of behaviour change interventions on physical activity behaviour of people living with chronic NCDs in Africa; patients ' experiences of these interventions; and to what extent interventions addressed patients ' concerns. These are the objectives of this study.",
      "reason": "The authors explicitly state the need for the review by identifying a gap in the existing literature."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_3",
      "quote": "No systematic review has examined the effects of behaviour change interventions on physical activity behaviour of people living with chronic NCDs in Africa",
      "reason": "The authors state that no similar systematic reviews exist, making this requirement inapplicable."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "Behaviour change techniques (BCTs) are replicable components of an intervention designed to alter/redirect causal processes that regulate behaviour with minimum delivery specifi cations that allow their identi fi cation.",
      "reason": "The authors describe the mechanism of action (BCTs) for the interventions being reviewed."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The review involves complex interventions, but no logic model is provided to show the hypothesized relationships between intervention components and outcomes."
    }
  ],
  "confidence": 95
}

