{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PRESENT",
      "chunk_id": "text_4",
      "quote": "Following PRISMA guidelines, 36 we searched MEDLINE, EMBASE, PsycINFO, CENTRAL, CINAHL, Web of Science, African Index Medicus (AIM) and AFROLIB (WHO ' s regional of fi ce database for Africa) from their inception dates up to 19 April 2017. We used a combination of Medical Subject Headings, free text terms and word variants for hypertension, diabetes, obesity and chronic musculoskeletal pain conditions, African search fi lter, 37 word variants for physical activity-related therapies and the search fi lters for three study types - clinical trials, qualitative and observational studies (supplemental fi le). 35 We also searched grey literature as described in the protocol. These conditions were selected because they are the most prevalent in Africa, 1,38 and may be the most easily modi fi ed by physical activity. Lung diseases were not included because it was envisaged that a signi fi cant proportion may be secondary to communicable diseases, such as tuberculosis.",
      "reason": "The text describes the search strategy and the conditions included/excluded, and references the protocol for further details on eligibility criteria. Additionally, Figure 1 (chunk_id: text_4) explicitly lists reasons for exclusion (Population: African Americans or African ethnic minority groups in non-African countries; Intervention: No physical activity component; Outcome evaluation: No physical activity behaviour assessment; Qualitative/quantitative studies not assessing experiences/perspectives)."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The provided text does not specify eligibility criteria regarding report characteristics such as dissemination year, language, or publication status."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The review does not explicitly discuss distinguishing between exclusion due to outcomes not being measured versus not being reported."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PRESENT",
      "chunk_id": "text_5",
      "quote": "Three-stage analyses were carried out using a mixed-studies synthesis design - the sequential explanatory synthesis. 43",
      "reason": "The review specifies the grouping of studies for synthesis: clinical studies were summarized using narrative synthesis (text_6), qualitative studies were reviewed using thematic synthesis (text_7), and a comparative analysis was performed (text_8)."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PRESENT",
      "chunk_id": "text_4",
      "quote": "These conditions were selected because they are the most prevalent in Africa, 1,38 and may be the most easily modi fi ed by physical activity. Lung diseases were not included because it was envisaged that a signi fi cant proportion may be secondary to communicable diseases, such as tuberculosis.",
      "reason": "The authors provide a rationale for the selection of specific chronic conditions and the exclusion of lung diseases."
    }
  ],
  "confidence": 90
}

